/**
 * frontend/src/CameraRecognition.jsx - VERSION FIXÉE
 * À REMPLACER
 * ✅ Caméra qui démarre vraiment
 * ✅ Capture frames
 * ✅ Envoie embeddings
 * ✅ Affiche résultats
 */

import React, { useRef, useState, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = () => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  // ============ STATE ============
  const [isStreaming, setIsStreaming] = useState(false);
  const [status, setStatus] = useState('idle'); // idle, running, error, success
  const [recentDetections, setRecentDetections] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(false);
  const [stream, setStream] = useState(null);

  // ============ CAMERA CONTROL ============

  const startCamera = async () => {
    try {
      console.log('📷 [CAMERA] Starting camera...');
      setLoading(true);
      setStatus('idle');
      setRecentDetections([]);

      // ✅ Demander accès caméra
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 },
          facingMode: 'user'
        },
        audio: false
      });

      console.log('✅ [CAMERA] Camera started!');
      console.log('✅ [CAMERA] Stream tracks:', mediaStream.getTracks().length);

      // ✅ Associer stream à vidéo
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;

        // ✅ Attendre que vidéo se charge
        videoRef.current.onloadedmetadata = () => {
          console.log('✅ [CAMERA] Video metadata loaded');
          videoRef.current.play().catch(err => {
            console.error('❌ [CAMERA] Play failed:', err);
          });
        };
      }

      setStream(mediaStream);
      setIsStreaming(true);
      setStatus('running');
      setLoading(false);

      // ✅ Démarrer capture frames
      startFrameCapture();
    } catch (error) {
      console.error('❌ [CAMERA] Error starting camera:', error);

      let errorMsg = 'Camera error';
      if (error.name === 'NotAllowedError') {
        errorMsg = 'Permission camera refusée. Clique sur autoriser.';
      } else if (error.name === 'NotFoundError') {
        errorMsg = 'Caméra non trouvée. Branche une caméra USB.';
      } else if (error.name === 'NotReadableError') {
        errorMsg = 'Caméra en utilisation par une autre app.';
      }

      setStatus('error');
      alert('❌ ' + errorMsg);
      setLoading(false);
    }
  };

  const stopCamera = () => {
    console.log('🛑 [CAMERA] Stopping camera...');

    if (stream) {
      stream.getTracks().forEach(track => {
        console.log('🛑 [CAMERA] Stopping track:', track.kind);
        track.stop();
      });
      setStream(null);
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setIsStreaming(false);
    setStatus('idle');
    setRecentDetections([]);
  };

  // ============ FRAME CAPTURE ============

  const captureFrame = async () => {
    try {
      if (!videoRef.current || !canvasRef.current) {
        console.warn('⚠️ [CAPTURE] Video or canvas ref missing');
        return;
      }

      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        console.error('❌ [CAPTURE] Canvas context failed');
        return;
      }

      // ✅ Définir dimensions canvas
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;

      // ✅ Dessiner frame vidéo
      ctx.drawImage(videoRef.current, 0, 0);

      // ✅ Convertir en base64
      const imageBase64 = canvas.toDataURL('image/jpeg', 0.9);

      console.log('📸 [CAPTURE] Frame captured, size:', imageBase64.length);

      // ✅ Envoyer pour extraction embedding
      await extractAndRecognize(imageBase64);
    } catch (error) {
      console.error('❌ [CAPTURE] Error:', error);
    }
  };

  const extractAndRecognize = async (imageBase64) => {
    try {
      console.log('👤 [RECOGNIZE] Extracting embedding from frame...');

      // ✅ ÉTAPE 1: Extraire embedding
      const extractResponse = await attendanceAPI.extractEmbedding(imageBase64);

      if (!extractResponse.data.success) {
        console.warn('⚠️ [RECOGNIZE] No face in frame:', extractResponse.data.error);
        setStatus('running');
        return;
      }

      console.log('✅ [RECOGNIZE] Embedding extracted');
      const embedding = extractResponse.data.embedding;

      // ✅ ÉTAPE 2: Reconnaître
      console.log('👤 [RECOGNIZE] Recognizing...');
      const recognizeResponse = await attendanceAPI.recognize(embedding);

      const result = recognizeResponse.data;

      if (result.success) {
        // ✅ MATCH TROUVÉ!
        console.log('✅ [RECOGNIZE] Match found!', result);

        setStatus('success');
        addDetection({
          name: result.student,
          confidence: result.confidence,
          time: result.timestamp,
          email: result.email,
          message: result.message
        });

        // Son de succès (optionnel)
        playSound('success');

        // Reset après 2 sec
        setTimeout(() => setStatus('running'), 2000);
      } else {
        // ❌ Pas de match
        console.log('⚠️ [RECOGNIZE] No match', result);
        setStatus('running');
      }
    } catch (error) {
      console.error('❌ [RECOGNIZE] Error:', error.response?.data || error.message);
      setStatus('running');
    }
  };

  const startFrameCapture = () => {
    console.log('🎬 [CAPTURE] Starting frame capture loop...');
    let frameCount = 0;

    const captureLoop = setInterval(async () => {
      if (!isStreaming) {
        console.log('🛑 [CAPTURE] Stopping capture loop');
        clearInterval(captureLoop);
        return;
      }

      frameCount++;

      // ✅ Capturer chaque frame (plus rapide = mieux pour reconnaissance)
      if (videoRef.current?.readyState === videoRef.current?.HAVE_ENOUGH_DATA) {
        await captureFrame();
      } else {
        console.warn('⚠️ [CAPTURE] Video not ready');
      }
    }, 500); // ✅ Capture toutes les 500ms (2 FPS - bon équilibre)
  };

  const addDetection = (detection) => {
    setRecentDetections(prev => [detection, ...prev].slice(0, 10));
  };

  // ============ HELPERS ============

  const playSound = (type) => {
    try {
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = audioContext.createOscillator();
      const gain = audioContext.createGain();

      oscillator.connect(gain);
      gain.connect(audioContext.destination);

      if (type === 'success') {
        oscillator.frequency.value = 800;
        gain.gain.setValueAtTime(0.3, audioContext.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.3);
        oscillator.start(audioContext.currentTime);
        oscillator.stop(audioContext.currentTime + 0.3);
      }
    } catch (error) {
      console.warn('⚠️ Audio failed:', error);
    }
  };

  // ============ CLEANUP ============

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  // ============ RENDER ============

  return (
    <div style={styles.container}>
      <div style={styles.mainGrid}>
        {/* VIDEO SECTION */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>📷 Flux Vidéo En Direct</h3>

          {/* VIDEO */}
          <div style={styles.videoContainer}>
            <video
              ref={videoRef}
              style={{
                ...styles.video,
                backgroundColor: isStreaming ? '#000' : '#f0f0f0'
              }}
              playsInline
              autoPlay
              muted
            />

            {/* STATUS OVERLAY */}
            <div
              style={{
                ...styles.statusOverlay,
                backgroundColor: {
                  idle: 'rgba(0, 0, 0, 0.3)',
                  running: 'rgba(59, 130, 246, 0.3)',
                  success: 'rgba(16, 185, 129, 0.3)',
                  error: 'rgba(239, 68, 68, 0.3)'
                }[status]
              }}
            >
              <p style={styles.statusText}>
                {status === 'idle' && '⏹️ Caméra arrêtée'}
                {status === 'running' && '🎥 En cours...'}
                {status === 'success' && '✅ Match trouvé!'}
                {status === 'error' && '❌ Erreur'}
              </p>
            </div>
          </div>

          {/* CANVAS HIDDEN */}
          <canvas ref={canvasRef} style={{ display: 'none' }} />

          {/* BUTTONS */}
          <div style={styles.buttonGroup}>
            {!isStreaming ? (
              <button
                onClick={startCamera}
                style={{
                  ...styles.btn,
                  backgroundColor: COLORS.success,
                  opacity: loading ? 0.6 : 1,
                  cursor: loading ? 'not-allowed' : 'pointer'
                }}
                disabled={loading}
              >
                {loading ? '⏳ Démarrage...' : '🎥 Démarrer Caméra'}
              </button>
            ) : (
              <button
                onClick={stopCamera}
                style={{
                  ...styles.btn,
                  backgroundColor: COLORS.danger
                }}
              >
                🛑 Arrêter Caméra
              </button>
            )}
          </div>
        </div>

        {/* STATS SECTION */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>📊 Détections Récentes</h3>

          {recentDetections.length === 0 ? (
            <div style={styles.emptyState}>
              <p>Aucune détection pour le moment</p>
              <p style={{ fontSize: '0.85rem', color: COLORS.textMuted }}>
                Montre ton visage à la caméra
              </p>
            </div>
          ) : (
            <div style={styles.detectionsList}>
              {recentDetections.map((detection, idx) => (
                <div key={idx} style={styles.detectionCard}>
                  <div style={styles.detectionHeader}>
                    <strong>{detection.name}</strong>
                    <span style={styles.confidenceBadge}>
                      {(detection.confidence * 100).toFixed(1)}%
                    </span>
                  </div>
                  <p style={styles.detectionEmail}>{detection.email}</p>
                  <p style={styles.detectionTime}>🕐 {detection.time}</p>
                  <p style={styles.detectionMessage}>{detection.message}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

